import { v7 as uuidv7 } from "uuid";
import { prisma } from "@formbricks/database";
import { Prisma, Webhook } from "@formbricks/database/prisma";
import { PrismaErrorType } from "@formbricks/database/types/error";
import { ZId } from "@formbricks/types/common";
import {
  DatabaseError,
  InvalidInputError,
  ResourceNotFoundError,
  UnknownError,
} from "@formbricks/types/errors";
import { generateWebhookSecret } from "@/lib/crypto";
import { validateInputs } from "@/lib/utils/validate";
import { validateWebhookUrl } from "@/lib/utils/validate-webhook-url";
import { getTranslate } from "@/lingodotdev/server";
import {
  WebhookDeliveryTimeoutError,
  sendSignedWebhookRequest,
} from "@/modules/integrations/webhooks/lib/send-signed-webhook";
import { isDiscordWebhook } from "@/modules/integrations/webhooks/lib/utils";
import { TWebhookInput } from "../types/webhooks";

const getWebhookTestErrorMessage = async (statusCode: number): Promise<string | null> => {
  switch (statusCode) {
    case 500: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_internal_server_error");
    }
    case 404: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_not_found_error");
    }
    case 405: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_method_not_allowed_error");
    }
    case 502: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_bad_gateway_error");
    }
    case 503: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_service_unavailable_error");
    }
    case 504: {
      const t = await getTranslate();
      return t("workspace.integrations.webhooks.endpoint_gateway_timeout_error");
    }
    default:
      return null;
  }
};

export const updateWebhook = async (
  webhookId: string,
  webhookInput: Partial<TWebhookInput>
): Promise<boolean> => {
  if (webhookInput.url) {
    await validateWebhookUrl(webhookInput.url);
  }

  try {
    await prisma.webhook.update({
      where: {
        id: webhookId,
      },
      data: {
        name: webhookInput.name,
        url: webhookInput.url,
        triggers: webhookInput.triggers,
        surveyIds: webhookInput.surveyIds || [],
      },
    });

    return true;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const deleteWebhook = async (id: string): Promise<boolean> => {
  try {
    await prisma.webhook.delete({
      where: {
        id,
      },
    });

    return true;
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === PrismaErrorType.RecordNotFound
    ) {
      throw new ResourceNotFoundError("Webhook", id);
    }
    throw new DatabaseError(`Database error when deleting webhook with ID ${id}`);
  }
};

export const createWebhook = async (
  workspaceId: string,
  webhookInput: TWebhookInput,
  secret?: string
): Promise<Webhook> => {
  await validateWebhookUrl(webhookInput.url);

  try {
    if (isDiscordWebhook(webhookInput.url)) {
      throw new UnknownError("Discord webhooks are currently not supported.");
    }

    const signingSecret = secret ?? generateWebhookSecret();

    const webhook = await prisma.webhook.create({
      data: {
        ...webhookInput,
        surveyIds: webhookInput.surveyIds || [],
        secret: signingSecret,
        workspace: {
          connect: {
            id: workspaceId,
          },
        },
      },
    });

    return webhook;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    if (!(error instanceof InvalidInputError)) {
      throw new DatabaseError(`Database error when creating webhook for workspace ${workspaceId}`);
    }

    throw error;
  }
};

export const getWebhooks = async (workspaceId: string): Promise<Webhook[]> => {
  validateInputs([workspaceId, ZId]);

  try {
    const webhooks = await prisma.webhook.findMany({
      where: {
        workspaceId,
      },
      orderBy: {
        createdAt: "desc",
      },
    });
    return webhooks;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new DatabaseError(error.message);
    }

    throw error;
  }
};

export const testEndpoint = async (url: string, secret?: string): Promise<boolean> => {
  if (isDiscordWebhook(url)) {
    throw new UnknownError("Discord webhooks are currently not supported.");
  }

  try {
    // Same transport as real deliveries (SSRF validation, DNS pinning, signing, redirect policy,
    // timeout), so what the button proves is what the background worker will do.
    const { statusCode } = await sendSignedWebhookRequest({
      url,
      secret,
      body: JSON.stringify({ event: "testEndpoint" }),
      messageId: uuidv7(),
    });

    // With `redirect: "manual"` undici returns the actual 30x. Surface it as a clear error instead of
    // a misleading success; with `redirect: "follow"` (internal URLs allowed) this branch is unreachable.
    if (statusCode >= 300 && statusCode < 400) {
      throw new InvalidInputError("Webhook endpoint returned a redirect, which is not allowed");
    }

    const errorMessage = await getWebhookTestErrorMessage(statusCode);

    if (errorMessage) {
      throw new InvalidInputError(errorMessage);
    }

    return true;
  } catch (error) {
    if (error instanceof WebhookDeliveryTimeoutError) {
      throw new UnknownError(`Request timed out after ${Math.round(error.timeoutMs / 1000)} seconds`);
    }

    if (error instanceof InvalidInputError || error instanceof UnknownError) {
      throw error;
    }

    throw new UnknownError(
      `Error while fetching the URL: ${error instanceof Error ? error.message : "Unknown error occurred"}`
    );
  }
};

/**
 * GET /api/v3/responses — list responses for a workspace, newest first.
 *
 * Raw `searchParams` rather than a wrapper-parsed schema, matching the surveys list: the query
 * carries bracket-style `filter[...]` families that a flat Zod object cannot describe, and the
 * cursor's 400 has to name `cursor` specifically rather than fail as a generic parse error.
 *
 * A thin adapter on purpose: the orchestration lives in the operation and the service, which the MCP
 * server also calls directly with no wrapper around them.
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { withV3ResponsesReadMetrics } from "./lib/metrics";
import { createV3Response, listV3Responses } from "./lib/operations";
import { ZV3CreateResponseBody } from "./lib/schemas";

export const GET = withV3ResponsesReadMetrics(
  "list",
  withV3ApiWrapper({
    auth: "both",
    handler: async ({ req, authentication, requestId, instance }) =>
      listV3Responses({
        searchParams: new URL(req.url).searchParams,
        authentication,
        requestId,
        instance,
      }),
  })
);

/**
 * POST /api/v3/responses — record a real submission.
 *
 * The workspace is resolved from the body's `surveyId`, never supplied, so the caller cannot choose
 * the scope it is authorized against. An empty strict query means any query parameter is a 400.
 */
export const POST = withV3ApiWrapper({
  auth: "both",
  action: "created",
  targetType: "response",
  schemas: { body: ZV3CreateResponseBody, query: ZV3EmptyQuery },
  handler: async ({ authentication, parsedInput, auditLog, requestId, instance }) =>
    createV3Response({
      authentication,
      body: parsedInput.body,
      auditLog,
      requestId,
      instance,
    }),
});

/**
 * /api/v3/action-classes - list a workspace's action classes (read-only).
 * Session cookie or x-api-key; scope by workspaceId only. Lets API/MCP clients discover the
 * action-class ids referenced by app-survey triggers (`distribution.triggers[].actionClassId`).
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3WorkspaceListQuery } from "@/app/api/v3/lib/schemas";
import { listV3ActionClasses } from "./lib/operations";

export const GET = withV3ApiWrapper({
  auth: "both",
  schemas: {
    query: ZV3WorkspaceListQuery,
  },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    return await listV3ActionClasses({
      workspaceId: parsedInput.query.workspaceId,
      limit: parsedInput.query.limit,
      cursor: parsedInput.query.cursor,
      authentication,
      requestId,
      instance,
    });
  },
});

import "server-only";
import { type TV3WorkspaceListParams, listV3WorkspaceResource } from "@/app/api/v3/lib/list-resource";
import { getActionClasses } from "@/lib/actionClass/service";
import { serializeV3ActionClass } from "../serializers";

export function listV3ActionClasses(params: TV3WorkspaceListParams): Promise<Response> {
  return listV3WorkspaceResource({
    ...params,
    resourceName: "action classes",
    fetchAll: getActionClasses,
    serialize: serializeV3ActionClass,
  });
}

import "server-only";
import { prisma } from "@formbricks/database";
import { Prisma } from "@formbricks/database/prisma";
import { logger } from "@formbricks/logger";
import type { TEmbeddedValueResponse } from "@formbricks/types/embedded-data-resolver";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import type {
  TResponse,
  TResponseData,
  TResponseDataValue,
  TResponseMeta,
  TResponseTtc,
  TResponseVariables,
} from "@formbricks/types/responses";
import type { InvalidParam } from "@/app/api/v3/lib/response";
import { sendToPipeline } from "@/app/lib/pipelines";
import { inlineSurveyEmbeddedFields } from "@/lib/embedded-data/survey-fields";
import { applyAnonymizePolicy } from "@/lib/response/anonymize";
import { getUniqueConstraintFields, isUniqueConstraintError } from "@/lib/utils/prisma-constraint";
import {
  evaluateResponseQuotas,
  loadQuotaEvaluationContext,
} from "@/modules/ee/quotas/lib/evaluation-service";
import { type TV3ResponseSurveyRow, v3ResponseReadSelect, v3ResponseSurveySelect } from "./service";

/**
 * The database half of the v3 response writes.
 *
 * Split from `service.ts` rather than appended to it because the two answer different questions: that
 * file is about reading a response without leaving its workspace, this one is about the ordering a
 * write has to respect. They share the selects and nothing else.
 *
 * Three orderings here are load-bearing and none of them is the obvious one:
 *
 * 1. **Reference checks run inside the transaction**, against the same snapshot the write uses. A
 *    `displayId` checked before the transaction can be claimed by a concurrent create in between.
 * 2. **Quota evaluation runs after the row exists**, in the same transaction, because a `reserved`
 *    quota operand resolves against the persisted row (ENG-1840) — and because it may itself flip
 *    `finished` to `true`.
 * 3. **Pipeline dispatch runs after commit**, and its `finished` comes from the row that was read
 *    back, never from the request body. A dispatch inside the transaction emits an event for a
 *    response a rollback then removes.
 */

/**
 * The survey a write is validated against: the read's select plus the three things only a write
 * needs. `endings` and `languages` back the two 422s that need no database of their own, and
 * `isAnonymizeResponsesEnabled` is what stops a caller writing submission context onto a survey
 * whose author turned anonymization on.
 */
export const v3WriteSurveySelect = {
  ...v3ResponseSurveySelect,
  questions: true,
  endings: true,
  isAnonymizeResponsesEnabled: true,
} satisfies Prisma.SurveySelect;

export type TV3WriteSurveyRow = Prisma.SurveyGetPayload<{ select: typeof v3WriteSurveySelect }> &
  Pick<TV3ResponseSurveyRow, "embeddedFields">;

/**
 * Resolve the survey a create is scoped by, **unscoped on purpose**.
 *
 * Same shape as `getResponseWorkspaceId`, and safe for the same reason: the caller feeds the
 * workspace straight into `requireV3WorkspaceAccess` and answers one 403 whether the survey is
 * missing or belongs to someone else. Resolving the scope from the survey rather than from a
 * client-supplied `workspaceId` is what makes it unforgeable.
 */
export async function getSurveyForV3Write(surveyId: string): Promise<TV3WriteSurveyRow | null> {
  const survey = await prisma.survey.findUnique({
    where: { id: surveyId },
    select: v3WriteSurveySelect,
  });

  return survey ? { ...survey, embeddedFields: inlineSurveyEmbeddedFields(survey) } : null;
}

/**
 * What a write reads back, and why it is not the read select.
 *
 * The row has two consumers with different needs: the serializer, which wants exactly what a `GET`
 * returns, and the pipeline payload, which is Zod-parsed against `ZResponse` in-request and fails on
 * a partial shape. Reading once with the union is a query cheaper than reading twice, and it is the
 * only way the two can never disagree about what was persisted.
 */
export const v3WriteReadbackSelect = {
  ...v3ResponseReadSelect,
  contactAttributes: true,
  tags: {
    select: {
      tag: { select: { id: true, createdAt: true, updatedAt: true, name: true, workspaceId: true } },
    },
  },
} satisfies Prisma.ResponseSelect;

export type TV3WriteReadbackRow = Prisma.ResponseGetPayload<{ select: typeof v3WriteReadbackSelect }>;

/**
 * The columns quota evaluation needs off the row it just wrote.
 *
 * Not a convenience: `evaluateResponseQuotas` builds the `reserved` operand map with
 * `buildServerEmbeddedValues`, whose catalog accessors read `meta.country`, `meta.url`,
 * `meta.userAgent.browser`, `createdAt`/`updatedAt` and `ttc` off this row. Every accessor is
 * wrapped in a `try`/`catch` that answers `undefined`, so a row missing those columns does not
 * fail — it silently resolves every reserved operand as unset, and a quota conditioned on one of
 * them counts nothing. v1 and v2 hand over the full row, so a narrower select here would make v3
 * the one write path where such a quota stops counting, with nothing logged.
 *
 * Shaped so `toQuotaEvaluationRow` can build a `TEmbeddedValueResponse` out of it without an escape
 * hatch — which is what makes a future narrowing of this select a build failure rather than a quota
 * that quietly stops matching.
 */
const v3QuotaEvaluationSelect = {
  id: true,
  surveyId: true,
  createdAt: true,
  updatedAt: true,
  finished: true,
  language: true,
  data: true,
  variables: true,
  ttc: true,
  meta: true,
} satisfies Prisma.ResponseSelect;

/**
 * Narrow the written row to the slice quota evaluation reads, field by field.
 *
 * Written out rather than cast wholesale so the compiler is the guard: every field
 * `TEmbeddedValueResponse` declares has to come from a column `v3QuotaEvaluationSelect` asks for, and
 * narrowing that select stops being a silent behaviour change and becomes a build failure. The casts
 * are confined here because Prisma types the four JSON columns as `JsonValue`; they are the shapes
 * the write itself persisted a few lines earlier.
 */
const toQuotaEvaluationRow = (
  row: Prisma.ResponseGetPayload<{ select: typeof v3QuotaEvaluationSelect }>
): TEmbeddedValueResponse => ({
  id: row.id,
  surveyId: row.surveyId,
  createdAt: row.createdAt,
  updatedAt: row.updatedAt,
  finished: row.finished,
  language: row.language,
  data: row.data as TResponseData,
  variables: row.variables as TResponseVariables,
  ttc: row.ttc as TResponseTtc,
  meta: row.meta as TResponseMeta,
});

/** Read back a written response, scoped. `null` means it was removed between the write and the read. */
export async function readbackV3Response(
  responseId: string,
  { workspaceId }: { workspaceId: string }
): Promise<TV3WriteReadbackRow | null> {
  return prisma.response.findFirst({
    where: { id: responseId, survey: { workspaceId } },
    select: v3WriteReadbackSelect,
  });
}

/**
 * Resolve the contact a create attributes the response to, and snapshot its attributes.
 *
 * Scoped to the caller's workspace, so "not in this workspace" and "does not exist" are one answer —
 * which is what keeps it from being an existence oracle for the tenant next door.
 */
async function checkContact(
  tx: Prisma.TransactionClient,
  workspaceId: string,
  contactId: string
): Promise<{ issue?: InvalidParam; contactAttributes?: Prisma.JsonValue }> {
  const contact = await tx.contact.findFirst({
    where: { id: contactId, workspaceId },
    select: { id: true, attributes: { select: { value: true, attributeKey: { select: { key: true } } } } },
  });

  if (!contact) {
    return {
      issue: {
        name: "contactId",
        reason: "No contact with this id exists in this workspace.",
        code: "invalid_reference",
      },
    };
  }

  // Snapshotted at create time, exactly as v1 and v2 do. v3 never publishes it, but the pipeline
  // reads `contactAttributes.userId` to identify the respondent to integrations, and an export
  // written months later cannot reconstruct what the attributes were on the day.
  return {
    contactAttributes: Object.fromEntries(
      contact.attributes.map(({ attributeKey, value }) => [attributeKey.key, value])
    ),
  };
}

/** A display belongs to one survey and backs at most one response. Both halves are checked here. */
async function checkDisplay(
  tx: Prisma.TransactionClient,
  surveyId: string,
  displayId: string,
  excludeResponseId?: string
): Promise<InvalidParam | null> {
  const display = await tx.display.findFirst({
    where: { id: displayId, surveyId },
    select: { id: true, response: { select: { id: true } } },
  });

  if (!display) {
    return {
      name: "displayId",
      reason: "No display with this id exists for this survey.",
      code: "invalid_reference",
    };
  }

  if (display.response && display.response.id !== excludeResponseId) {
    return {
      name: "displayId",
      reason: "This display already backs another response.",
      code: "duplicate_identifier",
    };
  }

  return null;
}

/** Single-use ids are unique per survey; the index enforces it, this reports it as the caller's. */
async function checkSingleUseId(
  tx: Prisma.TransactionClient,
  surveyId: string,
  singleUseId: string,
  excludeResponseId?: string
): Promise<InvalidParam | null> {
  const taken = await tx.response.findFirst({
    where: { singleUseId, surveyId, id: { not: excludeResponseId } },
    select: { id: true },
  });

  if (!taken) return null;

  return {
    name: "singleUseId",
    reason: "This single-use id has already been used for this survey.",
    code: "duplicate_identifier",
  };
}

/** One query for the whole set, then one issue per id that did not come back. */
async function checkTags(
  tx: Prisma.TransactionClient,
  workspaceId: string,
  tagIds: string[]
): Promise<InvalidParam[]> {
  const found = await tx.tag.findMany({ where: { id: { in: tagIds }, workspaceId }, select: { id: true } });
  const foundIds = new Set(found.map((tag) => tag.id));

  return tagIds
    .filter((tagId) => !foundIds.has(tagId))
    .map((tagId) => ({
      name: "tags",
      reason: `No tag with id '${tagId}' exists in this workspace.`,
      code: "invalid_reference" as const,
      identifier: tagId,
    }));
}

/**
 * The reference checks that need the database, run against the transaction's own snapshot.
 *
 * Every one of these is a 422 rather than a 404: the body is well-formed and the conflict is with
 * stored state. They are also all scoped to the workspace the caller is already authorized for, so
 * none of them can report on a resource outside it.
 *
 * Exported for `POST /api/v3/responses/validate`, which runs them against `prisma` rather than a
 * transaction. That is the honest dry run: outside a transaction these answer about the state now
 * rather than the state a write would see, which is exactly the guarantee a validate can offer.
 */
export async function collectReferenceIssues(
  tx: Prisma.TransactionClient,
  {
    workspaceId,
    surveyId,
    contactId,
    displayId,
    singleUseId,
    tagIds,
    excludeResponseId,
  }: {
    workspaceId: string;
    surveyId: string;
    contactId?: string;
    displayId?: string;
    singleUseId?: string;
    tagIds?: string[];
    excludeResponseId?: string;
  }
): Promise<{ issues: InvalidParam[]; contactAttributes: Prisma.JsonValue | undefined }> {
  const issues: InvalidParam[] = [];
  let contactAttributes: Prisma.JsonValue | undefined;

  if (contactId) {
    const result = await checkContact(tx, workspaceId, contactId);
    if (result.issue) issues.push(result.issue);
    contactAttributes = result.contactAttributes;
  }

  if (displayId) {
    const issue = await checkDisplay(tx, surveyId, displayId, excludeResponseId);
    if (issue) issues.push(issue);
  }

  if (singleUseId) {
    const issue = await checkSingleUseId(tx, surveyId, singleUseId, excludeResponseId);
    if (issue) issues.push(issue);
  }

  if (tagIds && tagIds.length > 0) {
    issues.push(...(await checkTags(tx, workspaceId, tagIds)));
  }

  return { issues, contactAttributes };
}

/**
 * A unique-constraint violation the pre-checks above lost a race to.
 *
 * Mapped to the same 422 the pre-check would have produced rather than to the generic 409, because
 * `POST`/`PATCH` do not document a 409 and a race must not be distinguishable from losing the check
 * outright.
 *
 * The columns come from `getUniqueConstraintFields`, which is the one place in the codebase allowed
 * to touch Prisma's `error.meta` — a shape Prisma states is not public API and which differs by
 * engine and version. Reading `meta.target` directly, as the obvious version of this does, matches
 * nothing on this repo: under Prisma 7 + `@prisma/adapter-pg` that key is absent, and since 7.10 the
 * adapter reports only the constraint name (`meta.driverAdapterError.cause.constraint.index`), which
 * the helper resolves back to columns. The obvious version therefore returns `null` for every real
 * race, and the caller rethrows into the generic 500.
 *
 * Mapping the race here, rather than letting it fall through to the generic 500, also keeps the raw
 * error out of the logs: the 500 branch logs it under `err`, and pino's error serializer copies every
 * enumerable property of `meta.driverAdapterError.cause`. `prisma-constraint.ts` warns against
 * surfacing those fields to a response *or a log*, and reading only the structured column list is how
 * this path honours it.
 */
function raceIssuesFromUniqueViolation(error: unknown): InvalidParam[] | null {
  if (!isUniqueConstraintError(error)) return null;

  const columns = getUniqueConstraintFields(error);

  if (columns.includes("singleUseId")) {
    return [
      {
        name: "singleUseId",
        reason: "This single-use id has already been used for this survey.",
        code: "duplicate_identifier",
      },
    ];
  }

  if (columns.includes("displayId")) {
    return [
      {
        name: "displayId",
        reason: "This display already backs another response.",
        code: "duplicate_identifier",
      },
    ];
  }

  return null;
}

/**
 * A scoped write that matched no row.
 *
 * The update's `where` carries `survey: { workspaceId }`, so P2025 means the response is gone or was
 * never this caller's — the same fact a pre-flight rejection establishes, and it has to answer the
 * same 403. `mapV3ThrownError` does not map raw Prisma errors, so without this translation the
 * promise in the scoped-update comment is not kept and the caller gets a 500 instead.
 *
 * Since the reference `connect`s became scoped too, P2025 also covers a contact, display or tag that
 * stopped matching its scope between the pre-flight check and the write.
 *
 * That answer is a 403, and it is **not** the body the routine case gets: a foreign reference caught
 * by the pre-flight is a 422 naming the field, which is what the contract documents. An earlier
 * version of this comment claimed the two matched — they do not, and the difference is worth being
 * precise about, because it is a documented-status divergence rather than a cosmetic one.
 *
 * It is still the right answer. The divergence is reachable only by losing a race — the reference was
 * in scope when checked and out of scope by the time the row was written — and in that state the
 * server cannot honestly say which field is at fault without re-reading and guessing. 403 with the
 * uniform body says the least, and says nothing a foreign-reference 403 elsewhere does not already
 * say. Which reference lost is recoverable from the logged Prisma error, and deliberately not from
 * the response.
 */
function rethrowScopedNotFound(error: unknown): void {
  if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2025") {
    // No id in the message: it is already correlated by requestId, and the operation keeps it out of
    // the body.
    throw new ResourceNotFoundError("Response", null);
  }
}

/** Either the row a write persisted, or the reference failures that stopped it. */
export type TV3WriteOutcome = { ok: true; responseId: string } | { ok: false; issues: InvalidParam[] };

export type TV3CreateResponsePersist = {
  workspaceId: string;
  survey: TV3WriteSurveyRow;
  finished: boolean;
  data: TResponseData;
  variables: Record<string, TResponseDataValue>;
  ttc: TResponseTtc;
  meta: TResponseMeta | undefined;
  tagIds: string[];
  endingId: string | null | undefined;
  language: string | null | undefined;
  contactId: string | undefined;
  displayId: string | undefined;
  singleUseId: string | undefined;
};

/**
 * Create one response, its tags and its quota links in a single transaction.
 *
 * The quota step can flip `finished` to `true` on the row it just counted, so nothing downstream may
 * assume the request body's `finished` is what got stored — the caller reads the row back.
 */
export async function createScopedResponse(input: TV3CreateResponsePersist): Promise<TV3WriteOutcome> {
  const { workspaceId, survey, meta, tagIds, contactId, displayId, singleUseId } = input;
  // `TagsOnResponses` is keyed on (responseId, tagId), so a repeated id is a composite-primary-key
  // violation rather than a redundant write. The contract calls `tags` a set; this is what makes it
  // one. Create already refuses duplicates at the schema, but the patch deliberately allows them.
  const uniqueTagIds = [...new Set(tagIds)];
  // Already resolved to one of the survey's own declared codes by `resolveV3WriteLanguage`, so it is
  // deliberately not canonicalized again here — that is what would push it out of the survey's set.
  const language = input.language ?? null;
  // Read before the transaction opens — see `TQuotaEvaluationContext`.
  const quotaContext = await loadQuotaEvaluationContext(survey.id);

  try {
    return await prisma.$transaction(async (tx) => {
      const { issues, contactAttributes } = await collectReferenceIssues(tx, {
        workspaceId,
        surveyId: survey.id,
        contactId,
        displayId,
        singleUseId,
        tagIds,
      });

      if (issues.length > 0) {
        return { ok: false as const, issues };
      }

      const created = await tx.response.create({
        data: {
          survey: { connect: { id: survey.id } },
          // Every `connect` below carries its own scope, not just an id. The checks above already
          // refused a foreign reference with a 422 naming the field, so this is the second layer:
          // it re-states the tenant predicate inside the write, where it reaches the SQL and rolls
          // the whole create back with P2025 on a non-match. That closes the window between check
          // and write, and — more to the point — it keeps holding if someone later moves, reorders
          // or forgets the checks. ENG-825, ENG-827 and ENG-1923 were all this shape.
          //
          // `display` is scoped by survey rather than workspace, and by `response: null`: Display has
          // no `workspaceId`, and workspace-only scoping would lose the cross-survey check ENG-825
          // was about. Verified against a real database — a foreign `surveyId` and an already-claimed
          // display both raise P2025 and leave no row.
          ...(displayId
            ? { display: { connect: { id: displayId, surveyId: survey.id, response: null } } }
            : {}),
          ...(contactId
            ? {
                contact: { connect: { id: contactId, workspaceId } },
                contactAttributes: contactAttributes ?? Prisma.JsonNull,
              }
            : {}),
          finished: input.finished,
          data: input.data,
          variables: input.variables,
          ttc: input.ttc,
          // "Anonymize responses" is a property of the survey, not of the door the response arrived
          // through, so it is applied here rather than trusted from the caller.
          meta: applyAnonymizePolicy(meta, survey.isAnonymizeResponsesEnabled) ?? {},
          language,
          endingId: input.endingId ?? null,
          singleUseId: singleUseId ?? null,
          ...(uniqueTagIds.length > 0
            ? {
                tags: {
                  create: uniqueTagIds.map((tagId) => ({
                    tag: { connect: { id: tagId, workspaceId } },
                  })),
                },
              }
            : {}),
        },
        select: v3QuotaEvaluationSelect,
      });

      await evaluateResponseQuotas({
        surveyId: survey.id,
        responseId: created.id,
        data: created.data as TResponseData,
        variables: created.variables as Record<string, TResponseDataValue>,
        language: language ?? "default",
        responseFinished: created.finished,
        // The row as persisted, so `reserved` quota operands resolve (ENG-1840).
        response: toQuotaEvaluationRow(created),
        tx,
        quotaContext,
      });

      return { ok: true as const, responseId: created.id };
    });
  } catch (error) {
    const raceIssues = raceIssuesFromUniqueViolation(error);
    if (raceIssues) return { ok: false, issues: raceIssues };

    rethrowScopedNotFound(error);
    throw error;
  }
}

export type TV3UpdateResponsePersist = {
  responseId: string;
  workspaceId: string;
  survey: TV3WriteSurveyRow;
  /** Only the keys the payload actually carried — an absent one must not be written as `undefined`. */
  patch: {
    finished?: boolean;
    endingId?: string | null;
    language?: string | null;
    data?: TResponseData;
    variables?: Record<string, TResponseDataValue>;
    tagIds?: string[];
    /**
     * Server-derived, never caller-supplied: `ttc` is create-only for a caller, but `_total` is a
     * derivation the shared update service performs on any write that finishes a response.
     */
    ttc?: TResponseTtc;
  };
};

/**
 * Apply a patch to one response, scoped, in a single transaction.
 *
 * `tags` is replace-the-set rather than add: the contract defines it as the complete set, so the
 * join rows are cleared and rewritten. Everything else is set only when the payload carried it —
 * spreading `undefined` into a Prisma `update` is the difference between "leave it" and "null it"
 * for the nullable columns, and `endingId` and `language` are both nullable.
 */
export async function updateScopedResponse({
  responseId,
  workspaceId,
  survey,
  patch,
}: TV3UpdateResponsePersist): Promise<TV3WriteOutcome> {
  // Read before the transaction opens — see `TQuotaEvaluationContext`.
  const quotaContext = await loadQuotaEvaluationContext(survey.id);

  try {
    return await prisma.$transaction(async (tx) => {
      const { issues } = await collectReferenceIssues(tx, {
        workspaceId,
        surveyId: survey.id,
        tagIds: patch.tagIds,
        excludeResponseId: responseId,
      });

      if (issues.length > 0) {
        return { ok: false as const, issues };
      }

      // Scoped `where`, never a bare id — a response outside the workspace matches nothing and
      // Prisma raises P2025, which the operation renders as the same 403 as a pre-flight rejection.
      const updated = await tx.response.update({
        where: { id: responseId, survey: { workspaceId } },
        data: {
          ...(patch.finished === undefined ? {} : { finished: patch.finished }),
          ...(patch.endingId === undefined ? {} : { endingId: patch.endingId }),
          ...(patch.language === undefined ? {} : { language: patch.language }),
          ...(patch.data === undefined ? {} : { data: patch.data }),
          ...(patch.ttc === undefined ? {} : { ttc: patch.ttc }),
          ...(patch.variables === undefined ? {} : { variables: patch.variables }),
          ...(patch.tagIds === undefined
            ? {}
            : {
                tags: {
                  deleteMany: {},
                  // Deduplicated — see the note in `createScopedResponse`.
                  // Scoped like the create path: the id alone would let a tag that left the
                  // workspace between check and write still attach.
                  create: [...new Set(patch.tagIds)].map((tagId) => ({
                    tag: { connect: { id: tagId, workspaceId } },
                  })),
                },
              }),
        },
        select: v3QuotaEvaluationSelect,
      });

      // Evaluated on every patch, not only on one that finishes the response. For a quota with
      // `countPartialSubmissions: false` the link row is written only once the response is finished,
      // so a create-only evaluation silently under-counts every response that finishes later.
      await evaluateResponseQuotas({
        surveyId: survey.id,
        responseId: updated.id,
        data: updated.data as TResponseData,
        variables: updated.variables as Record<string, TResponseDataValue>,
        language: updated.language ?? "default",
        responseFinished: updated.finished,
        response: toQuotaEvaluationRow(updated),
        tx,
        quotaContext,
      });

      return { ok: true as const, responseId: updated.id };
    });
  } catch (error) {
    const raceIssues = raceIssuesFromUniqueViolation(error);
    if (raceIssues) return { ok: false, issues: raceIssues };

    rethrowScopedNotFound(error);
    throw error;
  }
}

/**
 * Reshape a read-back row into the `TResponse` the pipeline is parsed against.
 *
 * Not cosmetic, and not optional. `enqueueResponsePipeline` Zod-parses its payload against
 * `ZResponse` **in-request**, and two of this row's fields are stored shapes rather than that shape:
 * `tags` arrives as join rows (`{ tag: … }[]`) where `ZResponse` wants `TTag[]`, and `contact`
 * carries an attribute row where it wants `{ id, userId }`. Handing the raw row over parses as a
 * failure, `sendToPipeline` throws, and because dispatch is deliberately non-fatal the request still
 * answers 201 — so the response is created and **no webhook, integration, follow-up or Hub ingestion
 * ever runs**, with nothing in the reply to say so. Found by smoke-testing a real create; a unit test
 * now parses this function's output against `ZResponse` so it cannot drift back.
 */
export function toV3PipelineResponse(row: TV3WriteReadbackRow): TResponse {
  return {
    id: row.id,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
    surveyId: row.surveyId,
    displayId: row.displayId,
    contact: row.contact
      ? {
          id: row.contact.id,
          // The snapshot taken at create time, not a live read: it is what the response was
          // attributed to, and it is the same source v1 and v2 hand the pipeline.
          ...((row.contactAttributes as Record<string, string> | null)?.userId
            ? { userId: (row.contactAttributes as Record<string, string>).userId }
            : {}),
        }
      : null,
    contactAttributes: (row.contactAttributes ?? null) as TResponse["contactAttributes"],
    finished: row.finished,
    endingId: row.endingId,
    data: (row.data ?? {}) as TResponse["data"],
    variables: (row.variables ?? {}) as TResponse["variables"],
    ttc: (row.ttc ?? {}) as TResponse["ttc"],
    tags: row.tags.map(({ tag }) => tag),
    meta: (row.meta ?? {}) as TResponse["meta"],
    singleUseId: row.singleUseId,
    language: row.language,
  };
}

/**
 * Emit the pipeline events for a committed write — after commit, and never fatally.
 *
 * **A queueing failure does not fail the request.** The row is already committed, so a 500 here
 * would tell a caller its write failed when it did not, and the retry that follows creates a second
 * response. A missed webhook is recoverable; a duplicated submission is not. `sendToPipeline`
 * rethrows on failure, which is why this wrapper exists at all.
 *
 * `finished` comes from the row that was read back rather than from the request: quota evaluation
 * can finish a response the caller submitted as partial, and that response has genuinely finished.
 */
export async function dispatchV3ResponsePipeline({
  event,
  workspaceId,
  surveyId,
  response,
  alsoFinished,
}: {
  event: "responseCreated" | "responseUpdated";
  workspaceId: string;
  surveyId: string;
  response: TV3WriteReadbackRow;
  alsoFinished: boolean;
}): Promise<void> {
  const payload = toV3PipelineResponse(response);

  const events: ("responseCreated" | "responseUpdated" | "responseFinished")[] = alsoFinished
    ? [event, "responseFinished"]
    : [event];

  for (const pipelineEvent of events) {
    try {
      await sendToPipeline({ event: pipelineEvent, workspaceId, surveyId, response: payload });
    } catch (error) {
      logger.error(
        { err: error, event: pipelineEvent, surveyId, workspaceId },
        "V3 response pipeline dispatch failed"
      );
    }
  }
}

import { z } from "zod";
import {
  zBatchDeleteResponsesRequest,
  zBatchDeleteResponsesV3Query,
  zCreateResponseRequest,
  zGetResponseV3Path,
  zPatchResponseRequest,
  zResponseDataMapInput,
  zResponseEmbeddedDataInput,
  zResponseTtcMap,
  zValidateResponseCreateRequest,
  zValidateResponsePatchRequest,
} from "@formbricks/api-v3-schemas";
import { declareReference } from "./reference-manifest";

/**
 * The request schemas of the v3 response routes.
 *
 * The shapes are generated from the contract (`@formbricks/api-v3-schemas`); this module adds what a
 * generated schema cannot carry, and nothing else:
 *
 * - the constraints the generator cannot express — `uniqueItems`, `minProperties`/`maxProperties`
 *   and the `if/then` value caps. Each one is pinned in the package's `EXPECTED_UNENFORCED`, and
 *   `write-schemas.test.ts` rejects a counterexample for every pin, so a constraint published on the
 *   contract cannot go unenforced here.
 * - the messages a caller reads in `invalid_params[].reason`.
 * - strictness for parameter objects, which the generator emits stripping because OpenAPI has no way to
 *   close a parameter list.
 * - the reference declarations of ENG-2861, which must sit on the exact instances the bodies expose.
 *
 * Compose first, refine last: Zod 4 refuses `.extend` over a key once a schema has refinements, and a
 * `.refine` clones its schema — so each declaration below targets the instance that ends up in the
 * final shape.
 */

/** `uniqueItems`, as a refinement. Shared with MCP tools that call the operations directly. */
export const hasUniqueItems = (values: readonly unknown[]): boolean => new Set(values).size === values.length;
export const RESPONSE_IDS_UNIQUE_MESSAGE = "Response ids must be unique";

/**
 * The response id is a path parameter, so it is validated here rather than trusted: an unparseable id
 * must answer 400 before any query runs, not 500 from Prisma (ENG-483 is that bug on the v1 route).
 * `GET`, `PATCH` and `DELETE` share the one `ResponseIdPath` parameter, so any of their path schemas
 * serves.
 */
export const ZV3ResponseIdParams = z.strictObject(zGetResponseV3Path.shape);
export type TV3ResponseIdParams = z.infer<typeof ZV3ResponseIdParams>;

/**
 * `POST /api/v3/responses/batch-delete`.
 *
 * The cap and the uniqueness rule are the contract's, and both are enforced here rather than left to
 * the service: an oversized batch must answer 400 before it reaches a `deleteMany`, and duplicates
 * would make `deleted` unreconcilable against `ids.length` for no benefit to the caller. The rule sits
 * on the array, not the body, so it still reports when another field of the body is also wrong.
 */
export const ZV3BatchDeleteResponsesQuery = z.strictObject(zBatchDeleteResponsesV3Query.shape);
export type TV3BatchDeleteResponsesQuery = z.infer<typeof ZV3BatchDeleteResponsesQuery>;

export const ZV3BatchDeleteResponsesBody = zBatchDeleteResponsesRequest.extend({
  ids: zBatchDeleteResponsesRequest.shape.ids.refine(hasUniqueItems, {
    message: RESPONSE_IDS_UNIQUE_MESSAGE,
  }),
});
export type TV3BatchDeleteResponsesBody = z.infer<typeof ZV3BatchDeleteResponsesBody>;

/**
 * Cardinality caps on a stored answer, per the ENG-1652 input policy — the same reason `tags` and the
 * batch-delete body are capped.
 *
 * Both are far past any real survey: a multi-select answer holds at most one entry per choice, and a
 * response holds at most one entry per element. Without them a single request inside the 2 MB body
 * limit can store an array of tens of thousands of entries, and every later reader pays for it per
 * entry — the serializer's per-answer mapping, export columns, and the positional probe the "Other"
 * response filter emits (ENG-3161), whose window is sized from the survey's choice count rather than
 * from the stored array.
 *
 * v3-only, and additive: the same unbounded shape reaches `ZResponseData` through the v1 and v2 write
 * paths, where capping it would reject payloads that work today.
 */
export const MAX_RESPONSE_DATA_VALUES = 1_000;
export const MAX_RESPONSE_DATA_KEYS = 500;

/**
 * `ResponseDataMapInput`: the stored answer map with the write-side bounds.
 *
 * The contract caps each value with `if/then` — an array at most 1000 items, a matrix at most 1000
 * rows — and the map with `maxProperties`. The value caps refine the generated value union and the
 * key cap refines the map, which reports issues exactly as the per-value `.max()` schema did: a value
 * over its cap and a map over 500 keys are both reported, while a value of the wrong shape fails the
 * map's parse and Zod then skips the key cap. The array cap raises Zod's own `too_big` issue, so its
 * `reason` reads the way a `.max()` would.
 */
const ZV3ResponseDataValue = zResponseDataMapInput.valueType.superRefine((value, ctx) => {
  if (Array.isArray(value)) {
    if (value.length > MAX_RESPONSE_DATA_VALUES) {
      ctx.addIssue({
        code: "too_big",
        origin: "array",
        maximum: MAX_RESPONSE_DATA_VALUES,
        inclusive: true,
        input: value,
      });
    }
  } else if (typeof value === "object" && Object.keys(value).length > MAX_RESPONSE_DATA_VALUES) {
    ctx.addIssue({
      code: "custom",
      input: value,
      message: `A matrix answer may hold at most ${MAX_RESPONSE_DATA_VALUES} rows`,
    });
  }
});

const ZV3ResponseDataInput = z
  .record(zResponseDataMapInput.keyType, ZV3ResponseDataValue)
  .refine((entries) => Object.keys(entries).length <= MAX_RESPONSE_DATA_KEYS, {
    message: `A response may answer at most ${MAX_RESPONSE_DATA_KEYS} fields`,
  });

/**
 * The same key cap `data` carries, for the other two element-keyed maps on this body.
 *
 * `embeddedData` needs it for a second reason beyond storage: every name that matches no declared
 * field becomes its own `invalid_params` entry, and the entry repeats the name in both `name` and
 * `reason`. Uncapped, a 2 MB body of distinct short names answers with a 422 several times its own
 * size — the request is rejected, and the rejection is the expensive part. Only Hub-relayed
 * `invalid_params` are bounded (`hub-errors.ts`); locally generated ones are not.
 */
const withKeyCap = <T extends z.ZodType<Record<string, unknown>>>(schema: T, what: string) =>
  schema.refine((entries) => Object.keys(entries).length <= MAX_RESPONSE_DATA_KEYS, {
    message: `A response may carry at most ${MAX_RESPONSE_DATA_KEYS} ${what}`,
  });

/** Embedded Data accepts scalars only, plus `null` to clear a field — per `ResponseEmbeddedDataInput`. */
const ZV3EmbeddedDataInput = withKeyCap(zResponseEmbeddedDataInput, "Embedded Data fields");

/**
 * Per-element timing, in milliseconds. Values are not bounded on purpose — the contract clamps rather
 * than rejects, because noisy client telemetry should never cost a caller their response. The clamp
 * lives in the service.
 */
const ZV3TtcInput = withKeyCap(zResponseTtcMap, "timing entries");

const createShape = zCreateResponseRequest.shape;
const patchShape = zPatchResponseRequest.shape;

/**
 * Bounded like the batch-delete body. Without the cap one 2 MB request becomes a `WHERE id IN (…)` of
 * tens of thousands of ids plus that many join-row inserts, all inside the write transaction. Unique on
 * create only, as the contract has it: a patch applies its tags as a set, and the service deduplicates
 * them before writing the join rows.
 */
const ZV3CreateTags = createShape.tags
  .unwrap()
  .refine(hasUniqueItems, { message: "Tag ids must be unique" })
  .optional();

/**
 * Every value on a body that names something outside it, declared once (ENG-2861).
 *
 * `reference-manifest.test.ts` reads the bodies, not this list: a new field — including one a spec edit
 * adds through generation — fails there until it is classified here. The point is that the set cannot
 * grow quietly: the twelve response BOLA fixes were each a field nobody knew was a reference.
 */
const fk = (resolvedAgainst: string) => ({ kind: "fk" as const, resolvedAgainst });
const local = (resolvedAgainst: string) => ({ kind: "document-local" as const, resolvedAgainst });
const TAGS_RESOLVED = "Tag filtered by workspaceId in one query, and connected scoped in the write";

declareReference(createShape.surveyId, fk("Survey, resolved and authorized by workspace before the write"));
declareReference(
  createShape.contactId,
  fk("Contact filtered by workspaceId, and connected scoped in the write")
);
declareReference(
  createShape.displayId,
  fk("Display filtered by surveyId and unclaimed, and connected scoped in the write")
);
declareReference(ZV3CreateTags, fk(TAGS_RESOLVED));
declareReference(patchShape.tags, fk(TAGS_RESOLVED));
for (const shape of [createShape, patchShape]) {
  declareReference(shape.endingId, local("the survey's own endings"));
  declareReference(shape.language, local("the survey's own enabled languages"));
}
declareReference(
  ZV3ResponseDataInput,
  local("the survey's element ids; file-upload values additionally carry an embedded-id")
);
declareReference(ZV3EmbeddedDataInput, local("the survey's declared Embedded Data field names"));
declareReference(
  createShape.singleUseId,
  local("unused for this survey — a token, scoped by surveyId rather than owned elsewhere")
);

/**
 * `POST /api/v3/responses`.
 *
 * Three required fields and nothing implied: `surveyId`, `finished` and `data`. Everything the
 * caller may not set is absent from the shape rather than stripped afterwards, so strictness turns an
 * attempt into a 400 naming the key instead of a silent drop — which is the difference between a
 * caller learning that `createdAt` is server-owned and one believing they backdated a response.
 */
export const ZV3CreateResponseBody = zCreateResponseRequest.extend({
  data: ZV3ResponseDataInput,
  embeddedData: ZV3EmbeddedDataInput.optional(),
  ttc: ZV3TtcInput.optional(),
  tags: ZV3CreateTags,
});
export type TV3CreateResponseBody = z.infer<typeof ZV3CreateResponseBody>;

/**
 * `PATCH /api/v3/responses/{responseId}`.
 *
 * Six patchable fields, and at least one of them — an empty body is a 400 rather than a no-op 200,
 * because a caller sending nothing has a bug and a 200 would hide it.
 */
export const ZV3PatchResponseBody = zPatchResponseRequest
  .extend({
    data: ZV3ResponseDataInput.optional(),
    embeddedData: ZV3EmbeddedDataInput.optional(),
  })
  .refine((body) => Object.keys(body).length > 0, { message: "At least one field must be provided" });
export type TV3PatchResponseBody = z.infer<typeof ZV3PatchResponseBody>;

/**
 * `POST /api/v3/responses/validate`.
 *
 * A union discriminated on `operation`, each arm carrying the body the real call would take, like
 * `ZV3SurveyValidationRequestBody`. The envelope is strict and its failures are the endpoint's only
 * 400 — `data` is any value precisely because problems inside it are the point of the endpoint and come
 * back as a `200` with `valid: false`.
 *
 * `data` is required rather than merely `unknown`: Zod treats an `unknown` field as satisfiable by an
 * absent key, so without the check `{ "operation": "create" }` would validate an empty document and
 * report it as a caller error rather than as the malformed envelope it is.
 */
const ZV3ValidationDocument = declareReference(
  z.unknown().refine((value) => value !== undefined, { message: "Required" }),
  local("the nested create or patch body, whose own fields carry their declarations")
);

/**
 * The envelope's own `responseId`. A dry run resolves it exactly as a real patch does —
 * `getResponseWorkspaceId`, then the scoped read — so validate cannot be used to probe whether a
 * response exists in someone else's workspace.
 */
declareReference(
  zValidateResponsePatchRequest.shape.responseId,
  fk("Response, via getResponseWorkspaceId then the workspace-scoped read")
);

export const ZV3ResponseValidationRequestBody = z.discriminatedUnion("operation", [
  zValidateResponseCreateRequest.extend({ operation: z.literal("create"), data: ZV3ValidationDocument }),
  zValidateResponsePatchRequest.extend({ operation: z.literal("patch"), data: ZV3ValidationDocument }),
]);
export type TV3ResponseValidationRequestBody = z.infer<typeof ZV3ResponseValidationRequestBody>;

"use server";

import { z } from "zod";
import { ZId } from "@formbricks/types/common";
import { ResourceNotFoundError } from "@formbricks/types/errors";
import { assertCan } from "@/lib/authorization";
