  list: (input: TWorkflowListKeyInput) => [...workflowKeys.lists(), input] as const,
  details: () => [...workflowKeys.all, "detail"] as const,
  detail: (workflowId: string) => [...workflowKeys.details(), workflowId] as const,
};

