  const locale = i18n.resolvedLanguage ?? i18n.language ?? \"en-US\";
  const router = useRouter();

  // Workspace id is available on the webhook; the parent page provides it as a route param,
  // but we read it from the workspace relation on the webhook row itself.
  const workspaceId = (webhook as unknown as Record<string, string>)[\"workspaceId\"] ?? \"\";

  const { mutate: duplicate, isPending: isDuplicating } = useDuplicateWebhook(workspaceId);

  const handleDuplicate = () => {
    duplicate(
      { webhookId: webhook.id },
      {
        onSuccess: () => {
          toast.success(t(\"workspace.integrations.webhooks.webhook_duplicated_successfully\"));
          router.refresh();
        },
        onError: (error) => {
          toast.error(getFormattedErrorMessage(error));
        },
      }
    );
  };

  return (
    <div className=\"mt-2 grid h-auto grid-cols-14 content-center rounded-lg py-2 hover:bg-slate-100\">
      <div className=\"col-span-3 flex items-center truncate pl-6 text-sm\">
        <div className=\"flex items-center\">
          <div className=\"text-left\">
            {webhook.name ? (
              <div className=\"text-left\">
                <div className=\"font-medium text-slate-900\">{webhook.name}</div>
                <div className=\"text-xs text-slate-400\">{webhook.url}</div>
              </div>
            ) : (
              <div className=\"font-medium text-slate-900\">{webhook.url}</div>
            )}
          </div>
        </div>
      </div>
      <div className=\"col-span-1 my-auto text-center text-sm text-slate-800\">
        <Badge type=\"gray\" size=\"tiny\" text={webhook.source || t(\"common.user\")} className=\"capitalize\" />
      </div>
      <div className=\"col-span-4 my-auto flex min-w-0 items-center justify-center gap-x-2 text-sm text-slate-800\">
        {renderSelectedSurveysText(webhook, surveys)}
        {hasRestrictedAttachedSurvey(surveyVisibilityEnabled, webhook.surveyIds, surveys) && (
          <RestrictedSurveyHint kind=\"paused\" />
        )}
      </div>
      <div className=\"col-span-2 my-auto text-center text-sm text-slate-800\">
        {renderSelectedTriggersText(webhook, t)}
      </div>
      <div className=\"col-span-1 my-auto text-center text-sm whitespace-nowrap text-slate-500\">
        {timeSince(webhook.createdAt.toString(), locale)}
      </div>
      <div className=\"col-span-1 my-auto text-center text-sm whitespace-nowrap text-slate-500\">
        {timeSince(webhook.updatedAt.toString(), locale)}
      </div>
      <div className=\"col-span-1 flex items-center justify-center gap-x-1\">
        <Button
          size=\"sm\"
          variant=\"secondary\"
          className=\"h-7 px-2 text-xs\"
          onClick={handleDuplicate}
          loading={isDuplicating}
          disabled={isDuplicating}>
          <CopyIcon className=\"size-3.5\" />
          {t(\"common.duplicate\")}
        </Button>
      </div>
    </div>
  );
};
EOF"

