"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { duplicateWebhook } from "../lib/api-client";
import { webhookKeys } from "../lib/query";

export const useDuplicateWebhook = (workspaceId: string) => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ webhookId, name }: { webhookId: string; name?: string }) =>
      duplicateWebhook(webhookId, name),
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: webhookKeys.list(workspaceId) });
    },
  });
};

"use client";

import { CopyIcon, MoreHorizontalIcon, TrashIcon } from "lucide-react";
import { TFunction } from "i18next";
import { useRouter } from "next/navigation";
import { useTranslation } from "react-i18next";
import { toast } from "react-hot-toast";
